        map["Հղումները կարելի է ստուգել Cloudflare-ի վտանգավոր կայքերի ցանկով։ Այդ դեպքում KHOSQ-ի սերվեր կուղարկվեն միայն կայքերի անունները (օրինակ՝ example.com)՝ ոչ ամբողջ հղումը, ոչ նամակը, ոչ ուղարկողի անունը։ Սերվերը դրանք չի պահում և չի գրանցում, իսկ Cloudflare-ը ստանում է միայն կայքի անունը։ Այդ պահին անունը չգաղտնագրված է։ Ստուգումը հետո կատարվում է ինքնաբերաբար, քանի դեռ անջատիչը միացված է Կարգավորումներում։"] = arrayOf("The links can be checked against Cloudflare’s list of dangerous sites. Then only the site names (for example example.com) are sent to the KHOSQ server: not the whole link, not the message, not the sender’s name. The server does not store or log them, and Cloudflare receives only the site name. At that moment the name is not encrypted. After that the check runs automatically while the switch in Settings stays on.", "Ссылки можно проверить по списку опасных сайтов Cloudflare. Тогда на сервер KHOSQ отправляются только названия сайтов (например, example.com): не вся ссылка, не сообщение и не имя отправителя. Сервер их не хранит и не записывает, а Cloudflare получает только название сайта. В этот момент название не зашифровано. Дальше проверка выполняется автоматически, пока включён переключатель в настройках.")
        map["Թույլատրել և ստուգել հղումները"] = arrayOf("Allow and check the links", "Разрешить и проверять ссылки")
        map["Ինչ անել"] = arrayOf("What to do", "Что делать")
        map["Երբեք մի ասա SMS կոդ, քարտի տվյալներ, գաղտնաբառ կամ PIN՝ նույնիսկ եթե ասում են, որ բանկից են։ Բանկը այդ տվյալները նամակով երբեք չի խնդրում։"] = arrayOf("Never tell an SMS code, card details, a password or a PIN, even if they say they are from the bank. A bank never asks for these in a message.", "Никогда не сообщайте код из СМС, данные карты, пароль или ПИН, даже если говорят, что они из банка. Банк никогда не просит их в сообщении.")
        map["Այս մարդուն դու չես ընդունել. եթե չես սպասում նրա նամակին, մի պատասխանիր և մի բացիր հղումները։"] = arrayOf("You have not accepted this person. If you were not expecting their message, do not reply and do not open the links.", "Вы не принимали этого человека. Если вы не ждали его сообщения, не отвечайте и не открывайте ссылки.")
        map["Եթե նամակը գալիս է ծանոթից, զանգիր նրան ուրիշ ճանապարհով. նրա հաշիվը կարող է կոտրված լինել։"] = arrayOf("If the message is from someone you know, call them another way; their account may have been hacked.", "Если сообщение пришло от знакомого, позвоните ему другим способом: его аккаунт могли взломать.")
        map["Սա ավտոմատ ստուգում է, այն կարող է սխալվել։ Եթե ոչինչ չի գտնվել, դա դեռ չի նշանակում, որ նամակն անվտանգ է։ Ամբողջ ստուգումը կատարվում է քո հեռախոսում։"] = arrayOf("This is an automatic check and it can be wrong. If nothing was found, that does not yet mean the message is safe. The whole check runs on your phone.", "Это автоматическая проверка, и она может ошибаться. Если ничего не найдено, это ещё не значит, что сообщение безопасно. Вся проверка выполняется на вашем телефоне.")
        map["Բողոքել"] = arrayOf("Report", "Пожаловаться")
        map["«Բողոքել»-ը պատրաստում է բողոքի տեքստը, և դու ինքդ ընտրում ես՝ որտեղ ուղարկել (օրինակ՝ քո փոստին)։ KHOSQ-ը ոչինչ ինքնաբերաբար չի ուղարկում։"] = arrayOf("“Report” prepares the text of a complaint and you choose where to send it (for example to your own email). KHOSQ sends nothing by itself.", "«Пожаловаться» готовит текст жалобы, а вы сами выбираете, куда её отправить (например, на свою почту). KHOSQ ничего не отправляет сам.")
